return items.map(item => {
  let text = item.json.property_raw_data || '';

  // Turn escaped newlines/tabs into real ones
  text = text.replace(/\\n/g, '\n');
  text = text.replace(/\\t/g, '\t');

  // Fix common mojibake / broken UTF-8 characters
  text = text
    .replace(/â€™/g, "'")
    .replace(/â€œ/g, '"')
    .replace(/â€/g, '"')
    .replace(/â€“/g, '–')
    .replace(/â€”/g, '—')
    .replace(/â€¦/g, '…')
    .replace(/Â/g, '');

  // Remove markdown formatting symbols but keep the words
  text = text
    .replace(/^#{1,六肖/gm, '')         // remove headings like # ## ###
    .replace(/\*\*(.*?)\*\*/g, '$1')     // bold
    .replace(/\*(.*?)\*/g, '$1')         // italics
    .replace(/`{1,3}/g, '');             // backticks

  // Clean extra spaces/newlines
  text = text.replace(/\n{3,}/g, '\n\n').trim();

  return {
    json: {
      cleaned_text: text
    }
  };
});

const techniques = [
  "SCQA",
  "PEEL",
  "SOAR",
  "5W1H",
  "BAR",
  "PAS",
  "Pyramid",
  "PREP",
  "FAB",
  "AIDA"
];

return items.map(item => {
  const text =
    item.json?.output?.[0]?.content?.[0]?.text || "";

  const selected = text
    .split(",")
    .map(t => t.trim());

  const result = {};

  for (const technique of techniques) {
    result[technique] = selected.includes(technique);
  }

  return {
    json: result
  };
});

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
