const all = $input.all().map(i => i.json);

function pick(prefix) {
  const found = all.find(item =>
    item[`${prefix}_gate`] !== undefined ||
    item[`${prefix}_revision_required`] !== undefined ||
    item[`${prefix}_complaint_count`] !== undefined ||
    item[`${prefix}_resolved_issues`] !== undefined ||
    item[`${prefix}_global_revision_guidance`] !== undefined
  );

  return {
    type: prefix,
    gate: found?.[`${prefix}_gate`] ?? null,
    revision_required: found?.[`${prefix}_revision_required`] ?? false,
    complaint_count: found?.[`${prefix}_complaint_count`] ?? 0,
    resolved_issues: found?.[`${prefix}_resolved_issues`] ?? [],
    global_revision_guidance: found?.[`${prefix}_global_revision_guidance`] ?? []
  };
}

return [
  {
    json: {
      revision_summary: {
        ethics: pick('ethics'),
        legal: pick('legal'),
        vision: pick('vision')
      }
    }
  }
];

