  const rawText =
    item.json?.output?.[0]?.content?.[0]?.text ||
    item.json?.content?.[0]?.text ||
    item.json?.text ||
    "";

  const cleanedText = String(rawText)
    .replace(/\r\n/g, "\n")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();

  const titleMatch = cleanedText.match(/^#\s*(.+)$/m);
  const title = titleMatch ? titleMatch[1].trim() : "";

  let technique = "";
  if (/SCQA/i.test(title)) technique = "SCQA";
  else if (/PEEL/i.test(title)) technique = "PEEL";
  else if (/5W1H/i.test(title)) technique = "5W1H";
  else if (/SOAR/i.test(title)) technique = "SOAR";
  else if (/CAR/i.test(title)) technique = "CAR";
  else if (/BAR/i.test(title)) technique = "BAR";
  else if (/PAS/i.test(title)) technique = "PAS";
  else if (/Pyramid/i.test(title)) technique = "Pyramid";
  else if (/PREP/i.test(title)) technique = "PREP";
  else if (/FAB/i.test(title)) technique = "FAB";
  else if (/AIDA/i.test(title)) technique = "AIDA";

  const body = cleanedText
    .replace(/^#\s*.+$/m, "")
    .trim();

  return {
    json: {
      technique,
      title,
      cleaned_text: cleanedText,
      body,
      raw_text: rawText
    }
  };
});

