const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Handle if output is nested under a key or is the root object
  const outputArray = data.output ?? (Array.isArray(data) ? data : [data]);

  for (const msg of outputArray) {
    for (const content of msg.content ?? []) {
      if (content.type === "output_text") {
        results.push({
          json: {
            text: content.text.replace(/^\"|\"$/g, "").trim()
          }
        });
      }
    }
  }
}

return results;

