}

return results;

return $input.all().map(item => {
  const text = (item.json.text || "").trim();
  const words = text ? text.split(/\s+/) : [];

  let first_line = "";
  let second_line = "";

  if (words.length === 2) {
    first_line = words[0];
    second_line = words[1];
  } else if (words.length === 3) {
    first_line = words.slice(0, 2).join(" ");
    second_line = words[2];
  } else if (words.length === 4) {
    first_line = words.slice(0, 2).join(" ");
    second_line = words.slice(2, 4).join(" ");
  }

  return {
    json: {
      ...item.json,
      first_line,
      second_line
    }
  };
});
